Because the array is sorted, keep one pointer at each end. If the sum is smaller than the target, move the left pointer forward. If it is larger, move the right pointer backward.

def pair_sum(values, target):
    left, right = 0, len(values) - 1
    while left < right:
        total = values[left] + values[right]
        if total == target:
            return values[left], values[right]
        if total < target:
            left += 1
        else:
            right -= 1
    return None

print(pair_sum([1, 2, 4, 6, 10], 8))  # (2, 6)

Complexity: O(n) time and O(1) extra space.

Track the required frequency of each character in t. Expand right until the window contains everything required, then shrink left as much as possible.

from collections import Counter

def minimum_window(s, t):
    if not s or not t:
        return ''
    need = Counter(t)
    have = {}
    required = len(need)
    formed = 0
    left = 0
    best = (float('inf'), 0, 0)
    for right, ch in enumerate(s):
        have[ch] = have.get(ch, 0) + 1
        if ch in need and have[ch] == need[ch]:
            formed += 1
        while formed == required:
            if right-left+1 < best[0]:
                best = (right-left+1, left, right)
            lc = s[left]
            have[lc] -= 1
            if lc in need and have[lc] < need[lc]:
                formed -= 1
            left += 1
    if best[0] == float('inf'):
        return ''
    return s[best[1]:best[2]+1]

print(minimum_window('ADOBECODEBANC', 'ABC'))  # BANC
